async function bafResolution(s, level, signal) {
  const fromBlock = await registrationStart(s, level);
  const [ethRows, ticketRows, whaleRows, skipped, header, schema] = await Promise.all([
    eventFacts(s, ['JackpotEthWin'], { contract: 'GAME', filters: { level, traitId: 420 }, fromBlock, signal }),
    // Tickets name their destination level, not the bracket that awarded them.
    eventFacts(s, ['JackpotTicketWin'], { contract: 'GAME', filters: { sourceLevel: [level, level + 1], traitId: 420 }, fromBlock, signal }),
    eventFacts(s, ['JackpotWhalePassWin'], { contract: 'GAME', filters: { source: 2 }, fromBlock, signal }),
    eventFacts(s, ['BafSkipped'], { contract: 'JACKPOTS', filters: { lvl: level }, fromBlock, signal }),
    s.field('JACKPOTS', 'bafLevel', level),
    loadSchema('JACKPOTS'),
  ]);
  const prizes = [...ethRows, ...ticketRows].sort(compareLogs);
  const eth = ethRows.map(jackpotWin), tickets = ticketRows.map(jackpotWin);
  const anchor = skipped[0] ?? prizes[0];
  const rng = anchor ? (await previousEvents(s.client, 'GAME','DailyRngApplied',anchor,{signal})).at(-1) : null;
  const day = skipped.length ? Number(skipped[0].args.day) : rng ? Number(rng.args.day) : null;
  const transactions = new Set(prizes.map(row => row.transactionHash));
  const whales = whaleRows.filter(row => transactions.has(row.transactionHash))
    .map(row => ({ ...jackpotWin(row), awardType: 'whale_pass_baf', level, day }));
  // A staged draw can emit prizes over multiple transactions before finalizing.
  // Its first payout must not make a partial receipt look like the final result.
  return { level, status: header.skipped || skipped.length ? 'skipped' : header.epoch > 0n ? 'closed' : 'open', day,
    rngWord: rng ? String(rng.args.finalWord) : null,
    cutMode: schema.abi.some(fragment => fragment.name === 'bafHeadWinner') ? 'staged' : 'legacy',
    // The first ETH event can be a small scatter prize; multiplying it by 20
    // does not recover the pool. Leave the estimate absent without that fact.
    estimatedPoolWei: null,
    wins: [...eth, ...tickets, ...whales].sort(compareLogs).map(row => ({ ...row, day })),
    awards: { ethCount: eth.length, ethUnique: new Set(eth.map(r=>r.winner)).size, ethTotal: prizeTotal(eth).total,
      ticketCount: tickets.length, ticketUnique: new Set(tickets.map(r=>r.winner)).size, ticketEntries: String(prizeTotal(tickets).total) } };
}

function payoutSpread(rows) {
  const perPlayer = new Map();
  for (const row of rows) perPlayer.set(row.winner,(perPlayer.get(row.winner)??0n)+BigInt(row.amount));
  const values=[...perPlayer.values()].sort((a,b)=>a<b?-1:a>b?1:0);
  if(values.length<2)return [false,true,false];
  const low=values[0],high=values.at(-1);if(low===high)return [true,true,true];
  const offset=values[Math.floor(values.length/2)]-low,third=(high-low)/3n;
  return offset<=third?[true,false,false]:offset<=third*2n?[false,true,false]:[false,false,true];
}
